    Expr val = cast<num_t>(i + j + (n - k)) * cast<num_t>(10) / cast<num_t>(n);
    init(k, j, i) = val;

    // ---- Schedule for initialization ------------------------------------
    // Memory layout is A(k, j, i) with k contiguous (dim 0).
    // Vectorize along k and parallelize along the outermost i dimension.
    Target target = get_host_target();
    Type t = type_of<num_t>();
    const int vec_width = target.natural_vector_size(t);

    Var ko("ko"), ki("ki");
    init
        .split(k, ko, ki, vec_width)   // k = ko * vec_width + ki
        .reorder(ki, j, ko, i)         // innermost: ki (vectorized), outermost: i
        .parallel(i)                   // distribute i-slices across cores
        .vectorize(ki);                // SIMD over contiguous k
    // ---------------------------------------------------------------------

    // Realize into both A and B so that B initially equals A
    init.realize(A);
    init.realize(B);
}

