    //
    // Layout: buffer dims are (k, j, i) with k contiguous in memory.
    // For both B_from_A and A_from_B we:
    //   * Vectorize along k (contiguous dimension).
    //   * Parallelize along the outermost i dimension (planes in i).
    //   * Keep j as a serial loop for good spatial locality.
    Target target = get_host_target();
