    B_from_A
        .compute_root()
        .split(k, ko, ki, vec_width)   // k = ko * vec_width + ki
        // New var order from innermost to outermost: ki, ko, j, i.
        // Loop nest: for i (outer) -> for j -> for ko -> for ki (inner).
        .reorder(ki, ko, j, i)
        .parallel(i)
        .vectorize(ki);

    A_from_B
        .compute_root()
        .split(k, ko, ki, vec_width)
        .reorder(ki, ko, j, i)
        .parallel(i)
        .vectorize(ki);
    // ---------------------------------------------------------------------

    // We want to update only the interior region:
    //   i, j, k in [1, n-2]
    // The boundary values remain unchanged (exactly as in the C code).
    //
