static void init_array(int n,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 3> B) {
    Var k("k"), j("j"), i("i");

    Func init("init");

    // i, j, k here are the C-style indices; buffer indices are (k, j, i)
