    init(k, j, i) = val;

    // Simple but reasonably efficient schedule:
    // - Make k (the C "k" index / fastest-varying in memory) the inner loop.
    // - Vectorize along k.
    // - Parallelize across the outermost dimension (i), which is coarse-grain.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    init
        .reorder(k, j, i)   // k innermost for contiguous accesses
        .vectorize(k, vec_width)
        .parallel(i);

    // Realize into both A and B so that B initially equals A
    init.realize(A);
    init.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size and number of time steps.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 3D buffers.
    // Dimension order is (k, j, i) so that:
    //   A(i,j,k in C) <-> A(k, j, i) in Halide.
    Halide::Buffer<num_t, 3> A(n, n, n);
    Halide::Buffer<num_t, 3> B(n, n, n);

    // Initialize A and B.
    init_array(n, A, B);

    // Create ImageParams for A and B so that Halide pipelines can read them.
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam B_param(type_of<num_t>(), 3, "B_param");

    A_param.set(A);
    B_param.set(B);

    // Vars for 3D indexing (k, j, i) <-> (C's k, j, i).
    Var k("k"), j("j"), i("i");

    // One time-step consists of:
    //   1) B = stencil(A)
    //   2) A = stencil(B)
    //
    // We'll express these as two separate Halide Funcs:
    //   B_from_A: reads A_param, writes into B
    //   A_from_B: reads B_param, writes into A
    //
    // We only update interior points (i,j,k in [1, n-2]), as in the
    // original C loops. The boundaries remain unchanged.
    Func B_from_A("B_from_A");
    Func A_from_B("A_from_B");

    // Physical constants as Exprs in the working precision.
    Expr alpha = cast<num_t>(Expr(0.125));  // diffusion coefficient
    Expr one   = cast<num_t>(Expr(1.0));
    Expr six   = cast<num_t>(Expr(6.0));

    // Coefficient for the center cell after combining terms:
    //   center_new = alpha * (sum of 6 neighbors - 6*center) + center
    //              = (1 - 6*alpha)*center + alpha*sum_neighbors
    Expr center_coeff = one - six * alpha;

    // --- Stage 1: B = stencil(A) ---
    {
        Expr centerA =
            A_param(k, j, i);

        // Sum of the 6 axis-aligned neighbors of A(i,j,k).
        Expr neighborsA =
            A_param(k,     j,     i + 1) +
            A_param(k,     j,     i - 1) +
            A_param(k,     j + 1, i    ) +
            A_param(k,     j - 1, i    ) +
            A_param(k + 1, j,     i    ) +
            A_param(k - 1, j,     i    );

        // 7-point stencil, algebraically reduced to:
        //   B = center_coeff * center + alpha * neighbors_sum
        B_from_A(k, j, i) = center_coeff * centerA + alpha * neighborsA;
    }

    // --- Stage 2: A = stencil(B) ---
    {
        Expr centerB =
            B_param(k, j, i);

        Expr neighborsB =
            B_param(k,     j,     i + 1) +
            B_param(k,     j,     i - 1) +
            B_param(k,     j + 1, i    ) +
            B_param(k,     j - 1, i    ) +
            B_param(k + 1, j,     i    ) +
            B_param(k - 1, j,     i    );

        A_from_B(k, j, i) = center_coeff * centerB + alpha * neighborsB;
    }

    // We want to update only the interior region:
    //   i, j, k in [1, n-2]
    // The boundary values remain unchanged (exactly as in the C code).
    //
    // We'll realize into cropped "interior" views that alias the
    // underlying A and B storage, so that:
    //   - interior points are overwritten by the stencil
    //   - boundary points (index 0 and n-1) are untouched
    Halide::Buffer<num_t, 3> B_interior =
        B.cropped(0, 1, n - 2)
         .cropped(1, 1, n - 2)
         .cropped(2, 1, n - 2);

    Halide::Buffer<num_t, 3> A_interior =
        A.cropped(0, 1, n - 2)
         .cropped(1, 1, n - 2)
         .cropped(2, 1, n - 2);

    // -------------------------
    // Scheduling for performance
    // -------------------------

    // Use the host target to choose a reasonable vector width for this scalar type.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // For both stencils:
    // - Restrict the Vars to the interior region (improves bounds inference).
    // - Make k (dim 0, C's "k") the innermost loop to get unit-stride accesses.
    // - Vectorize along k.
    // - Parallelize across i (outermost dimension, C's "i"), which gives
    //   coarse-grain parallelism and good cache behavior for j,k sweeps.
    B_from_A
        .bound(k, 1, n - 2)
        .bound(j, 1, n - 2)
        .bound(i, 1, n - 2)
        .reorder(k, j, i)       // k inner (fastest-varying in memory)
        .vectorize(k, vec_width)
        .parallel(i);

    A_from_B
        .bound(k, 1, n - 2)
        .bound(j, 1, n - 2)
        .bound(i, 1, n - 2)
        .reorder(k, j, i)
        .vectorize(k, vec_width)
        .parallel(i);

    // Compile the kernels ahead of time to avoid measuring JIT cost.
    B_from_A.compile_jit(target);
    A_from_B.compile_jit(target);

    // Time the tsteps iterations.
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // First half-step: B = stencil(A) on the interior.
        B_from_A.realize(B_interior);

        // Second half-step: A = stencil(B) on the interior.
        A_from_B.realize(A_interior);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print out the final A array (similar to print_array in C).
    using namespace std::string_literals;
