        Expr centerB = B_param(k, j, i);

        Expr term_i = alpha *
                      (B_param(k, j, i + 1) - two * centerB + B_param(k, j, i - 1));
        Expr term_j = alpha *
                      (B_param(k, j + 1, i) - two * centerB + B_param(k, j - 1, i));
        Expr term_k = alpha *
                      (B_param(k + 1, j, i) - two * centerB + B_param(k - 1, j, i));

        A_from_B(k, j, i) = term_i + term_j + term_k + centerB;
