    B_from_A
        .compute_root()
        // Tile the (i, j) plane into tile_i x tile_j tiles.
        .tile(i, j, io, jo, ii, ji, tile_i, tile_j)
        // Fuse tile coords into a single index and parallelize across tiles.
        .fuse(io, jo, tile_index)
        .parallel(tile_index)
        // Ensure k is the innermost loop for contiguous vector loads/stores.
        .reorder(k, ii, ji, tile_index)
        // Vectorize along the contiguous k dimension.
        .vectorize(k, vec_width);

