    A_from_B
        .compute_root()
        .tile(i, j, io, jo, ii, ji, tile_i, tile_j)
        .fuse(io, jo, tile_index)
        .parallel(tile_index)
        .reorder(k, ii, ji, tile_index)
        .vectorize(k, vec_width);

