    // Schedule the initializer for good locality:
    //  - k (dim 0) is innermost and vectorized (contiguous in memory)
    //  - fuse j & i and parallelize across the 2D plane
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    Var ji("ji");
    init
        .fuse(j, i, ji)   // flatten (j,i) into a single loop
        .reorder(k, ji)   // k innermost, ji outermost
        .vectorize(k, vec_width)
        .parallel(ji);

    // Realize into both A and B so that B initially equals A
    init.realize(A);
    init.realize(B);
}

/** Common 7-point (axis-aligned) 3D stencil update:
 *
 *   out = center + alpha * (sum(neighbors) - 6 * center)
 *
 * where neighbors are +/-1 in each of k, j, i.
 */
static Expr stencil_update(const ImageParam &src,
                           Var k, Var j, Var i,
                           Expr alpha) {
    Expr center = src(k, j, i);

    Expr neighbors =
        src(k,     j,     i + 1) +
        src(k,     j,     i - 1) +
        src(k,     j + 1, i    ) +
        src(k,     j - 1, i    ) +
        src(k + 1, j,     i    ) +
        src(k - 1, j,     i    );

    Expr six = cast<num_t>(Expr(6.0));

    // center + alpha * (neighbors - 6 * center)
    return center + alpha * (neighbors - six * center);
}

/** Schedule for a 3D stencil Func f(k,j,i) writing into a dense
 *  Buffer laid out as (k contiguous, then j, then i).
 *
 *  - Fuse (j,i) so we can parallelize across the 2D plane.
 *  - Make k innermost and vectorize it for SIMD.
 */
static void schedule_stencil(Func &f,
                             Var k, Var j, Var i,
                             const Target &target) {
    Var ji("ji");
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    f
        // Flatten the (j,i) iteration space into a single dimension.
        .fuse(j, i, ji)
        // Make k the innermost loop for unit-stride memory access.
        .reorder(k, ji)
        // Vectorize along k (contiguous dimension).
        .vectorize(k, vec_width)
        // Parallelize across the fused j/i plane.
        .parallel(ji);
}

